code.java:
class Solution {
    public int averageValue(int[] nums){
        int sum=0,count=0;
        for(int value:nums)if(value%6==0){
            sum+=value;
            count++;
        }
        return count==0?0:sum/count;
    }
}

code.kotlin:
class Solution {
    fun averageValue(nums:IntArray):Int{
        var sum=0;
        var count=0;
        for(value in nums)if(value%6==0){
            sum+=value;
            count++
        };
        return if(count==0)0 else sum/count
    }
}

